package setup

import (
	"context"

	tea "github.com/charmbracelet/bubbletea"

	"github.com/anthnel/devdesk/internal/config"
	"github.com/anthnel/devdesk/internal/credentials"
	"github.com/anthnel/devdesk/internal/forge/session"
)

// ContextExistsMsg reports whether the named context already has a file on
// disk.
type ContextExistsMsg struct {
	Exists bool
	Err    error
}

func checkContextExistsCmd(name string) tea.Cmd {
	return func() tea.Msg {
		exists, err := config.ContextExists(name)
		return ContextExistsMsg{Exists: exists, Err: err}
	}
}

// TokenValidatedMsg reports the outcome of authenticating the forge token the
// user typed. A nil Err means the token is both valid and saved — Authenticate
// persists it via the resolved Storage as part of the same call.
type TokenValidatedMsg struct {
	Err error
}

func validateTokenCmd(contextName, secretBackend, forgeType, url, token string) tea.Cmd {
	return func() tea.Msg {
		sel := credentials.Select(contextName, secretBackend)
		_, err := session.NewAuth(sel.Storage).Authenticate(context.Background(), forgeType, url, token)
		return TokenValidatedMsg{Err: err}
	}
}

// ContextSavedMsg reports whether the context file was written.
type ContextSavedMsg struct {
	Err error
}

func saveContextCmd(cfg *config.Config, name string) tea.Cmd {
	return func() tea.Msg {
		return ContextSavedMsg{Err: config.SaveContext(cfg, name)}
	}
}

// CurrentContextSetMsg reports whether the new context became the active one.
type CurrentContextSetMsg struct {
	Err error
}

func setCurrentContextCmd(name string) tea.Cmd {
	return func() tea.Msg {
		return CurrentContextSetMsg{Err: config.SetCurrentContext(name)}
	}
}

package setup

import (
	"strings"

	"github.com/anthnel/devdesk/internal/config"
)

// buildConfig turns the wizard's answers into a full context configuration,
// starting from config.Default() the same way config.CreateContext does. It
// is a pure function on purpose: everything it needs is already collected on
// Model, so this is testable without driving the Bubble Tea loop.
//
// The forge token is deliberately absent here: it never lives in the config
// struct (internal/config/config.go's ForgeConfig doc comment), and
// validateTokenCmd already persists it via the resolved credentials.Storage.
func buildConfig(m Model) *config.Config {
	cfg := config.Default()

	cfg.App.SecretBackend = secretBackendOptions[m.secretBackendIdx]
	cfg.App.ContainerEngine = config.ContainerEngines()[m.containerEngineIdx]
	cfg.App.Theme = m.themeOptions[m.themeIdx]

	cfg.Forge.Type = config.ForgeTypes()[m.forgeTypeIdx]
	cfg.Forge.URL = strings.TrimSpace(m.forgeURLInput.Value())
	cfg.Forge.DefaultParentGroup = strings.TrimSpace(m.forgeNamespaceInput.Value())
	cfg.Forge.DefaultVisibility = m.visibilityValue
	cfg.Forge.CloneMethod = cloneMethodOptions[m.cloneMethodIdx]

	// Matches config.CreateContext: a freshly wizard-built context starts with
	// no monitors to manage.
	cfg.Status.Components = []config.ComponentConfig{}

	return cfg
}

package setup

import tea "github.com/charmbracelet/bubbletea"

// Run launches the `dk setup` wizard as a standalone full-screen program. It
// is the only entry point main.go needs from this package.
func Run() error {
	p := tea.NewProgram(New(), tea.WithAltScreen())
	_, err := p.Run()
	return err
}

package setup

import (
	"strings"

	"github.com/charmbracelet/lipgloss"

	"github.com/anthnel/devdesk/internal/config"
	"github.com/anthnel/devdesk/internal/forge"
	"github.com/anthnel/devdesk/internal/ui/components"
	"github.com/anthnel/devdesk/internal/ui/theme"
)

// View renders the wizard: the form, or whichever overlay is active on top
// of it (Rule 112 — a confirmation is a centered modal, never the viewport).
func (m Model) View() string {
	switch m.stage {
	case stageConfirmOverwrite, stageConfirmSetCurrent:
		return lipgloss.Place(m.width, m.height, lipgloss.Center, lipgloss.Center,
			m.confirmModal.View(),
			lipgloss.WithWhitespaceBackground(theme.ColorBackground))
	case stageDone:
		return m.renderDone()
	default:
		return m.renderForm()
	}
}

func (m Model) renderForm() string {
	var b strings.Builder

	b.WriteString(theme.TitleStyle.Render("DevDesk setup — new context"))
	b.WriteString("\n")
	b.WriteString(theme.EmptyLineBg(m.width) + "\n")

	v := forge.VocabularyFor(config.ForgeTypes()[m.forgeTypeIdx])

	fields := []string{
		renderTextField("Context name", m.contextNameInput.View(), m.focusedField == fieldContextName),
		renderCycleField("Secret backend", secretBackendOptions[m.secretBackendIdx], m.focusedField == fieldSecretBackend),
		renderCycleField("Container engine", config.ContainerEngines()[m.containerEngineIdx], m.focusedField == fieldContainerEngine),
		renderCycleField("Theme", m.themeOptions[m.themeIdx], m.focusedField == fieldTheme),
		renderCycleField("Forge", v.Name, m.focusedField == fieldForgeType),
		renderTextField(v.Name+" URL", m.forgeURLInput.View(), m.focusedField == fieldForgeURL),
		renderTextField("Default "+v.Namespace, m.forgeNamespaceInput.View(), m.focusedField == fieldForgeNamespace),
		renderCycleField("Visibility", m.visibilityValue, m.focusedField == fieldForgeVisibility),
		renderCycleField("Clone method", cloneMethodOptions[m.cloneMethodIdx], m.focusedField == fieldForgeCloneMethod),
		renderTextField(v.TokenLabel, m.forgeTokenInput.View(), m.focusedField == fieldForgeToken),
	}
	for _, f := range fields {
		b.WriteString(f)
		b.WriteString("\n\n")
	}

	b.WriteString("  " + theme.RenderButton("Create context", m.focusedField == fieldSubmit, "primary"))
	b.WriteString("\n\n")

	b.WriteString(m.footer.View(m.width, m.status()))
	b.WriteString("\n")
	b.WriteString(theme.HelpStyle.Render("  [↑↓] navigate  [←→] change  [enter] confirm  [esc] quit"))

	return b.String()
}

func (m Model) renderDone() string {
	var b strings.Builder

	b.WriteString(theme.TitleStyle.Render("Context ready"))
	b.WriteString("\n\n")
	b.WriteString(theme.Bg("Wrote " + m.savedPath))
	b.WriteString("\n")
	if m.currentContextWarning != "" {
		b.WriteString(lipgloss.NewStyle().Background(theme.ColorBackground).Foreground(theme.ColorError).
			Render(m.currentContextWarning))
		b.WriteString("\n")
	}
	b.WriteString("\n")
	b.WriteString(theme.Bg(`Run "dk" to start.`))
	b.WriteString("\n\n")
	b.WriteString(theme.HelpStyle.Render("  [enter] exit"))

	return b.String()
}

func (m Model) status() components.Status {
	if m.pending != "" {
		return components.Status{Text: m.pending, Spinner: true}
	}
	return components.Status{}
}

// renderTextField renders a single-line label over a textinput's view,
// following Rule 120: the focus indicator and chevron separator, no ":".
func renderTextField(label, valueView string, focused bool) string {
	var labelStr string
	if focused {
		labelStr = theme.KeyStyle.Render(theme.IconCircleSmall + " " + label + " " + theme.IconChevronRight)
	} else {
		labelStr = theme.Bg("  " + label + " " + theme.IconChevronRight)
	}
	return labelStr + "\n" + theme.Bg("  ") + valueView
}

// renderCycleField renders a closed-set field with the ←→ cycle pattern
// (Rule 132), the same layout CreationForm's resource-type field uses.
func renderCycleField(label, value string, focused bool) string {
	selectLabel := label + " " + theme.IconSelect + " "
	valueView := lipgloss.NewStyle().Background(theme.ColorBackground).Foreground(theme.ColorText).Render(value)
	if focused {
		return theme.KeyStyle.Render(theme.IconCircleSmall+" "+selectLabel+theme.IconChevronRight+" ") + valueView
	}
	return theme.Bg("  "+selectLabel+theme.IconChevronRight+" ") + valueView
}

